// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {FlashGovernanceArbiter} from "../src/FlashGovernanceArbiter.sol";

contract InvMutTest is Test {
    FlashGovernanceArbiter c;
    function setUp() public { c = new FlashGovernanceArbiter(address(new __InvMutHandleStub())); }

    function testFuzz_property(address initialDao, address newDao) public {
        // Keep the two fuzzed DAO addresses distinct so a successful setDAO must change the getter.
        vm.assume(initialDao != newDao);

        // Exercise the DAO update path with a permitted caller. The reference sets DAO = newDao;
        // the buggy version only clears the cached governer and leaves DAO untouched.
        vm.prank(initialDao);
        c.setDAO(initialDao);

        vm.prank(initialDao);
        c.setDAO(newDao);

        // General rule: after a permitted setDAO(x), the DAO getter must equal x.
        assertTrue(c.DAO() == newDao);
    }
}

